	    LOGGER.info("handling AssignAdvisorsToWealthFirmEvent - " );
	    
	    WealthFirm parentEntity = repository.findById(parentId).get();
	    Advisor child = registry.project( Advisor.class, addTo.getAdvisorId());
	    
